<script setup lang="ts">
/**
 * A field that holds a rich-text document: a comment, an issue's description, a note (`design/components/rich-text-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useId,
  useTemplateRef,
  watch,
  type Ref,
  type VNode,
} from 'vue'

import {
  Icon,
  RICH_TEXT_FORMATS,
  agentMember,
  createRichTextEditor,
  emptyRichText,
  enterToolbar,
  followSelectionBar,
  holdToolbarEscape,
  isRichTextEmpty,
  placeSelectionBar,
  placeTokenList,
  richTextFromText,
  richTextHref,
  richTextLength,
  richTextPlainText,
  serializeRichText,
  syncToolbarStop,
  toolbarFocusIn,
  toolbarFocusOut,
  toolbarKeydown,
  toolbarPress,
  toolbarStop,
  useControlRef,
  useListening,
  useTrackedSlots,
  type IconRole,
  type RichTextDocument,
  type RichTextEditor,
  type RichTextEditorEvent,
  type RichTextEditorState,
  type RichTextFormat,
  type RichTextRange,
  type RichTextSuggestionKey,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/rich-text-input.module.css'
import selectionBar from '@polymorph/recipes/controls/selection-bar.module.css'
import Button from './Button.vue'
import FormField from './FormField.vue'
import Input from './Input.vue'
import Menu from '../overlays/Menu.vue'
import Popover from '../overlays/Popover.vue'
import Separator from '../structure/Separator.vue'
import Skeleton from '../structure/Skeleton.vue'

export type RichTextInputMinRows = NonNullable<RichTextInputProps['minRows']>

export type RichTextInputMaxRows = NonNullable<RichTextInputProps['maxRows']>

export type RichTextToolbarPlacement = NonNullable<RichTextInputProps['toolbarPlacement']>

export interface RichTextEntityOption {
  id: string
  label: string
  description?: string
  icon?: IconRole
  leading?: VNode
  entityLabel?: string
}

export interface RichTextEntitySource {
  kind: string
  trigger: string
  label: string
  options: RichTextEntityOption[]
  filter?: 'contains' | 'startsWith' | false
  loading?: boolean
  error?: string
  onQueryChange?: (query: string) => void
}

export interface RichTextInputSelection {
  empty: boolean
  text: string
  range: RichTextRange
}

export interface RichTextInputEditor {
  focus(): void
  clear(): void
  insertText(text: string): void
  insertEntity(entity: { kind: string; id: string; label: string }): void
  annotate(id: string): boolean
  removeAnnotation(id: string): boolean
  readonly value: RichTextDocument
  readonly empty: boolean
  readonly length: number
  readonly overLimit: boolean
  readonly disabled: boolean
  readonly selection: RichTextInputSelection
}

export interface RichTextInputMessages {
  toolbar?: string
  selectionBar?: string
  selectionBarReady?: string
  bold?: string
  italic?: string
  strike?: string
  code?: string
  link?: string
  textStyle?: string
  paragraph?: string
  heading?: (level: 1 | 2 | 3) => string
  bulletList?: string
  orderedList?: string
  blockquote?: string
  codeBlock?: string
  undo?: string
  redo?: string
  linkForm?: string
  linkAddress?: string
  linkApply?: string
  linkRemove?: string
  linkInvalid?: string
  formatOn?: (format: string) => string
  formatOff?: (format: string) => string
  linkAdded?: string
  linkRemoved?: string
  inserted?: (label: string) => string
  undone?: string
  redone?: string
  count?: (length: number, maxLength: number) => string
  overLimit?: (over: number) => string
  withinLimit?: string
  submitEmpty?: string
  submitOverLimit?: (over: number) => string
  submitPending?: string
  suggestions?: (count: number) => string
  loadingSuggestions?: string
  noSuggestions?: string
}

export interface RichTextInputProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  ariaDescribedby?: string
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Focus at mount, with the caret at the end. For a surface that has already moved the person
   * here.
   */
  autoFocus?: boolean
  /**
   * Draws the default footer's cancel Button; needs `onCancel`.
   */
  cancelLabel?: string
  /**
   * The editable element.
   */
  controlRef?: Ref<HTMLDivElement | null>
  defaultValue?: RichTextDocument
  disabled?: boolean
  /**
   * The kinds of entity the field suggests, each with its trigger.
   */
  entities?: RichTextEntitySource[]
  /**
   * What the field allows. Default: all ten.
   */
  formats?: RichTextFormat[]
  id?: string
  invalid?: boolean
  /**
   * A soft limit in code points (`richTextLength`): draws the count, and marks the field invalid
   * past it.
   */
  maxLength?: number
  /**
   * How tall the text grows before it scrolls, in body lines. Default 12.
   */
  maxRows?: 6 | 12 | 'none' | 24
  /**
   * Every label and announcement, in the app's words.
   */
  messages?: RichTextInputMessages
  /**
   * The surface's minimum height, in body lines. Default 3.
   */
  minRows?: 1 | 3 | 6 | 12
  /**
   * Adds a hidden input holding `serializeRichText(value)`.
   */
  name?: string
  /**
   * The app is saving: the submit shows loading, the field is read-only, and a submit is
   * refused.
   */
  pending?: boolean
  placeholder?: string
  readOnly?: boolean
  /**
   * Draws the default footer's submit Button; needs `onSubmit`.
   */
  submitLabel?: string
  /**
   * Where the format controls are: a fixed row over the text, or a bar at the selected text.
   */
  toolbarPlacement?: 'fixed' | 'selection'
  value?: RichTextDocument
}

defineOptions({ name: 'RichTextInput', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<RichTextInputProps>(), {
  ariaRequired: undefined,
  autoFocus: false,
  disabled: false,
  entities: () => [],
  invalid: false,
  maxRows: 12,
  minRows: 3,
  pending: false,
  readOnly: false,
  toolbarPlacement: 'fixed',
})
const emit = defineEmits<{
  annotationSelect: [id: string]
  blur: []
  cancel: []
  change: [value: RichTextDocument]
  files: [files: File[]]
  focus: []
  submit: [value: RichTextDocument, editor: RichTextInputEditor]
}>()
const callerSlots = defineSlots<{
  footer?: (props: RichTextInputEditor) => unknown
  selectionActions?: (props: RichTextInputEditor) => unknown
  toolbar?: (props: RichTextInputEditor) => unknown
}>()
const slots = useTrackedSlots(callerSlots)
const uid = useId()
const listening = useListening()
const own = ref(props.defaultValue ?? emptyRichText())
const editorState = ref(null as RichTextEditorState | null)
const said = ref({ text: '', at: 0 })
const highlight = ref({ key: '', index: 0 })
const reported = ref(null as string | null)
const caretAnnotation = ref(null as string | null)
const press = ref(null as { entered: string | null } | null)
const linkOpen = ref(false)
const linkDraft = ref('')
const linkError = ref(undefined as string | undefined)
const linkTarget = ref(null as string | null)
const headingOpen = ref(false)
const headingByPointer = ref(false)
const byPointer = ref(false)
const textFocused = ref(false)
const barFocus = ref(false)
const selecting = ref(false)
const barDismissed = ref(null as string | null)
const barHeard = ref(false)
const actions = useTemplateRef<HTMLElement>('actions')
const bar = useTemplateRef<HTMLElement>('bar')
const controls = useTemplateRef<HTMLElement>('controls')
const linkForm = useTemplateRef<HTMLElement>('linkForm')
const panel = useTemplateRef<HTMLElement>('panel')
const root = useTemplateRef<HTMLElement>('root')
const toolbarRow = useTemplateRef<HTMLElement>('toolbarRow')
const [surface, attachSurface] = useControlRef(() => props.controlRef)
const held = computed(() => ({
  editor: null as RichTextEditor | null,
  handle: null as RichTextInputEditor | null,
}))
const say = computed(
  () =>
    ({
      ...{
        toolbar: 'Formatting',
        selectionBar: 'Selection',
        selectionBarReady: 'Controls for the selection are available: Alt+F10',
        bold: 'Bold',
        italic: 'Italic',
        strike: 'Strikethrough',
        code: 'Code',
        link: 'Link',
        textStyle: 'Text style',
        paragraph: 'Paragraph',
        heading: (level: 1 | 2 | 3) => `Heading ${level}`,
        bulletList: 'Bulleted list',
        orderedList: 'Numbered list',
        blockquote: 'Quote',
        codeBlock: 'Code block',
        undo: 'Undo',
        redo: 'Redo',
        linkForm: 'Link',
        linkAddress: 'Address',
        linkApply: 'Apply',
        linkRemove: 'Remove link',
        linkInvalid: 'Enter a web address, an email address or a phone number.',
        formatOn: (format: string) => `${format} on`,
        formatOff: (format: string) => `${format} off`,
        linkAdded: 'Link added',
        linkRemoved: 'Link removed',
        inserted: (label: string) => `${label} inserted`,
        undone: 'Undone',
        redone: 'Redone',
        count: (length: number, maxLength: number) => `${length} / ${maxLength}`,
        overLimit: (over: number) =>
          `${over} ${over === 1 ? 'character' : 'characters'} over the limit`,
        withinLimit: 'Within the limit',
        submitEmpty: 'There is nothing to submit yet.',
        submitOverLimit: (over: number) =>
          `Remove ${over} ${over === 1 ? 'character' : 'characters'} to submit.`,
        submitPending: 'Still saving.',
        suggestions: (count: number) => `${count} suggestions`,
        loadingSuggestions: 'Loading suggestions…',
        noSuggestions: 'No results',
      },
      ...(props.messages === undefined
        ? {}
        : Object.fromEntries(
            Object.entries(props.messages).filter(([, words]) => words !== undefined),
          )),
    }) as Required<RichTextInputMessages>,
)
const doc = computed(() => props.value ?? own.value)
const empty = computed(() => isRichTextEmpty(doc.value))
const length = computed(() => richTextLength(doc.value))
const over = computed(() =>
  props.maxLength === undefined ? 0 : Math.max(0, length.value - props.maxLength),
)
const overLimit = computed(() => over.value > 0)
const unwritable = computed(() => props.readOnly || props.pending)
const locked = computed(() => props.disabled || unwritable.value)
const editable = computed(() => !locked.value)
const allowed = computed(() =>
  RICH_TEXT_FORMATS.filter((format) => (props.formats ?? RICH_TEXT_FORMATS).includes(format)),
)
const has = computed(() => (format: RichTextFormat) => allowed.value.includes(format))
const kinds = computed(() =>
  props.entities.map((entry) => ({ kind: entry.kind, trigger: entry.trigger })),
)
const marks = computed(() =>
  (
    [
      ['bold', 'bold'],
      ['italic', 'italic'],
      ['strike', 'strikethrough'],
      ['code', 'code'],
    ] as const
  )
    .filter(([format]) => has.value(format))
    .map(([format, icon]) => ({ format, icon })),
)
const blocks = computed(() =>
  (
    [
      ['bulletList', 'list-bulleted'],
      ['orderedList', 'list-numbered'],
      ['blockquote', 'quote'],
      ['codeBlock', 'code-block'],
    ] as const
  )
    .filter(([format]) => has.value(format))
    .map(([format, icon]) => ({ format, icon })),
)
const surfaceId = computed(() => props.id ?? `${uid}-surface`)
const listId = computed(() => `${uid}-suggestions`)
const countId = computed(() => `${uid}-count`)
const active = computed(() => editorState.value?.active)
const can = computed(() => editorState.value?.can)
const selection = computed(() => ({
  empty: editorState.value?.collapsed ?? true,
  text: editorState.value?.selectedText ?? '',
  range: editorState.value?.range ?? { start: 0, end: 0 },
}))
const focusText = computed(() => () => held.value.editor?.focus())
const announce = computed(() => (words: string) => {
  said.value = { text: words, at: said.value.at + 1 }
})
const formatName = computed(
  () =>
    (format: Exclude<RichTextFormat, 'link'>): string =>
      format === 'heading' ? say.value.textStyle : say.value[format],
)
const heard = computed(() => (event: RichTextEditorEvent) => {
  if (event.type === 'format')
    announce.value(
      (event.active ? say.value.formatOn : say.value.formatOff)(formatName.value(event.format)),
    )
  else if (event.type === 'heading')
    announce.value(event.level === 0 ? say.value.paragraph : say.value.heading(event.level))
  else if (event.type === 'link')
    announce.value(event.active ? say.value.linkAdded : say.value.linkRemoved)
  else if (event.type === 'entity') announce.value(say.value.inserted(event.entity.label))
  else if (event.type === 'undo') announce.value(say.value.undone)
  else announce.value(say.value.redone)
})
const changed = computed(() => (next: RichTextDocument) => {
  if (props.maxLength !== undefined) {
    const was = richTextLength(doc.value) > props.maxLength
    const nextOver = Math.max(0, richTextLength(next) - props.maxLength)
    if (!was && nextOver > 0) announce.value(say.value.overLimit(nextOver))
    else if (was && nextOver === 0) announce.value(say.value.withinLimit)
  }
  own.value = next
  emit('change', next)
})
const replace = computed(() => (editor: RichTextEditor, next: RichTextDocument) => {
  editor.setValue(next)
  changed.value(editor.getValue())
})
const collator = computed(
  () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
)
const suggestion = computed(() => (editable.value ? (editorState.value?.suggestion ?? null) : null))
const source = computed(() =>
  ((token) =>
    token === null ? undefined : props.entities.find((entry) => entry.kind === token.kind))(
    suggestion.value,
  ),
)
const open = computed(() => suggestion.value !== null && source.value !== undefined)
const query = computed(() => suggestion.value?.query ?? '')
const needle = computed(() => query.value.normalize('NFC'))
const matches = computed(
  () => (label: string) =>
    ((candidate: string) =>
      needle.value === '' ||
      (source.value?.filter === 'startsWith'
        ? collator.value.compare(candidate.slice(0, needle.value.length), needle.value) === 0
        : Array.from({ length: Math.max(0, candidate.length - needle.value.length + 1) }, (_, at) =>
            candidate.slice(at, at + needle.value.length),
          ).some((part) => collator.value.compare(part, needle.value) === 0)))(
      label.normalize('NFC'),
    ),
)
const loading = computed(() => open.value && source.value?.loading === true)
const failed = computed(
  () =>
    open.value && !loading.value && source.value?.error !== undefined && source.value.error !== '',
)
const shown = computed(() =>
  !open.value || failed.value || source.value === undefined
    ? []
    : source.value.filter === false
      ? source.value.options
      : source.value.options.filter((option) => matches.value(option.label)),
)
const listKey = computed(() =>
  open.value && suggestion.value !== null ? `${suggestion.value.key}:${query.value}` : '',
)
const activeOption = computed(() =>
  shown.value.length === 0
    ? -1
    : highlight.value.key === listKey.value
      ? Math.min(highlight.value.index, shown.value.length - 1)
      : 0,
)
const listStatus = computed(() =>
  !open.value
    ? null
    : loading.value
      ? say.value.loadingSuggestions
      : failed.value
        ? (source.value?.error ?? '')
        : shown.value.length === 0
          ? say.value.noSuggestions
          : say.value.suggestions(shown.value.length),
)
const pick = computed(() => (index: number) => {
  const option = shown.value[index]
  const editor = held.value.editor
  const from = source.value
  if (option === undefined || from === undefined || editor === null) return
  reported.value = null
  editor.insertEntity({
    kind: from.kind,
    id: option.id,
    label: option.entityLabel ?? from.trigger + option.label,
  })
})
const suggestionKey = computed(() => (key: RichTextSuggestionKey): boolean => {
  if (!open.value) return false
  if (key === 'ArrowDown' || key === 'ArrowUp') {
    if (shown.value.length === 0) return false
    highlight.value = {
      key: listKey.value,
      index:
        key === 'ArrowDown'
          ? Math.min(activeOption.value + 1, shown.value.length - 1)
          : Math.max(activeOption.value - 1, 0),
    }
    return true
  }
  if (key === 'Enter') {
    if (activeOption.value === -1) return loading.value
    pick.value(activeOption.value)
    return true
  }
  if (key === 'Tab') {
    if (activeOption.value === -1) return false
    pick.value(activeOption.value)
    return true
  }
  held.value.editor?.dismissSuggestion()
  return true
})
const drawn = computed(
  () => (annotation: string) =>
    props.annotations === undefined || props.annotations.includes(annotation),
)
const stated = computed(() => (next: RichTextEditorState) => {
  editorState.value = next
  const token = next.suggestion
  const nextSource =
    token === null ? undefined : props.entities.find((entry) => entry.kind === token.kind)
  const key = token === null || nextSource === undefined ? null : token.key + ':' + token.query
  if (key !== reported.value) {
    reported.value = key
    if (token !== null && key !== null) nextSource?.onQueryChange?.(token.query)
  }
  const at = next.collapsed
    ? (next.annotations.find((annotation) => drawn.value(annotation)) ?? null)
    : null
  if (at !== null && at !== caretAnnotation.value) {
    if (press.value !== null) press.value = { entered: at }
    emit('annotationSelect', at)
  }
  caretAnnotation.value = at
})
const handle = computed(() =>
  ((next: RichTextInputEditor): RichTextInputEditor => {
    const last = held.value.handle
    if (
      last !== null &&
      last.value === next.value &&
      last.empty === next.empty &&
      last.length === next.length &&
      last.overLimit === next.overLimit &&
      last.disabled === next.disabled &&
      last.selection.empty === next.selection.empty &&
      last.selection.text === next.selection.text &&
      last.selection.range.start === next.selection.range.start &&
      last.selection.range.end === next.selection.range.end
    )
      return last
    held.value.handle = next
    return next
  })({
    focus: () => held.value.editor?.focus(),
    clear: () => held.value.editor?.clear(),
    insertText: (words: string) => held.value.editor?.insertText(words),
    insertEntity: (entity: { kind: string; id: string; label: string }) =>
      held.value.editor?.insertEntity(entity),
    annotate: (annotation: string) => held.value.editor?.annotate(annotation) ?? false,
    removeAnnotation: (annotation: string) =>
      held.value.editor?.removeAnnotation(annotation) ?? false,
    value: doc.value,
    empty: empty.value,
    length: length.value,
    overLimit: overLimit.value,
    disabled: locked.value,
    selection: selection.value,
  }),
)
const submit = computed(() => () => {
  if (!listening.submit || props.disabled) return
  if (props.pending) return announce.value(say.value.submitPending)
  if (empty.value) return announce.value(say.value.submitEmpty)
  if (overLimit.value) return announce.value(say.value.submitOverLimit(over.value))
  emit('submit', held.value.editor?.getValue() ?? doc.value, handle.value)
})
const openLink = computed(() => (next: boolean) => {
  if (next) {
    const target = held.value.editor?.getState().active.link ?? null
    linkDraft.value = target ?? ''
    linkError.value = undefined
    linkTarget.value = target
  }
  linkOpen.value = next
})
const applyLink = computed(() => (event: Event) => {
  event.preventDefault()
  event.stopPropagation()
  const raw = linkDraft.value.trim()
  const editor = held.value.editor
  if (
    raw === '' ||
    richTextHref(raw, { typed: true }) === null ||
    editor === null ||
    !editor.setLink(raw)
  ) {
    linkError.value = say.value.linkInvalid
    return
  }
  linkOpen.value = false
})
const removeLink = computed(() => () => {
  held.value.editor?.setLink(null)
  linkOpen.value = false
})
const requestLink = computed(() => () => {
  const editor = held.value.editor
  const anchored = props.toolbarPlacement === 'fixed' || barOpen.value
  if (editor === null || !editable.value || !editor.getState().can.link || !anchored) return
  openLink.value(true)
})
const level = computed(() =>
  active.value === undefined ? 0 : active.value.codeBlock ? -1 : active.value.heading,
)
const headingItems = computed(() =>
  ([0, 1, 2, 3] as const).map((choice) => ({
    kind: 'checkbox' as const,
    label: choice === 0 ? say.value.paragraph : say.value.heading(choice),
    checked: level.value === choice,
    onCheckedChange: () => chooseHeading.value(choice),
  })),
)
const openHeading = computed(() => (next: boolean) => {
  if (next) headingByPointer.value = byPointer.value
  headingOpen.value = next
})
const chooseHeading = computed(() => (choice: 0 | 1 | 2 | 3) => {
  held.value.editor?.setHeading(choice)
  headingOpen.value = false
})
const afterPopup = computed(() => (then: () => void) => {
  const view = root.value?.ownerDocument.defaultView
  view?.requestAnimationFrame(() => view.requestAnimationFrame(then))
})
const linkClosed = computed(() => () => {
  const popover = linkForm.value?.closest('[data-member="popover"]') ?? null
  afterPopup.value(() => {
    const owner = root.value?.ownerDocument
    const at = owner?.activeElement ?? null
    if (
      at === null ||
      at === owner?.body ||
      root.value?.contains(at) === true ||
      popover?.contains(at) === true
    )
      held.value.editor?.focus()
  })
})
const headingClosed = computed(() => () => {
  if (headingByPointer.value) afterPopup.value(() => held.value.editor?.focus())
})
const formatsInBar = computed(
  () => props.toolbarPlacement === 'selection' && editable.value && allowed.value.length > 0,
)
const actionsInBar = computed(() => !!slots.selectionActions && !props.disabled)
const rangeKey = computed(() => `${selection.value.range.start}:${selection.value.range.end}`)
const barPopup = computed(() => formatsInBar.value && (linkOpen.value || headingOpen.value))
const barOpen = computed(
  () =>
    (formatsInBar.value || actionsInBar.value) &&
    editorState.value !== null &&
    !editorState.value.collapsed &&
    (textFocused.value || barFocus.value || barPopup.value) &&
    !selecting.value &&
    barDismissed.value !== rangeKey.value,
)
const escape = computed(() => (): boolean => {
  if (open.value) {
    held.value.editor?.dismissSuggestion()
    return true
  }
  if (barOpen.value) {
    barDismissed.value = rangeKey.value
    return true
  }
  return false
})
const holdSurfaceEscape = computed(() => (element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const hold = (event: KeyboardEvent) => {
    if (event.key !== 'Escape' || event.isComposing || event.target !== element) return
    if (escape.value()) event.preventDefault()
  }
  view?.addEventListener('keydown', hold, true)
  return () => view?.removeEventListener('keydown', hold, true)
})
const holdEscapeIn = computed(
  () => (element: HTMLElement, now: () => HTMLElement | null | undefined) => {
    const view = element.ownerDocument.defaultView
    return view === null ? () => {} : holdToolbarEscape(view, now)
  },
)
const releaseSelecting = computed(() => (element: HTMLElement) => {
  const view = element.ownerDocument.defaultView
  const release = () => {
    selecting.value = false
  }
  view?.addEventListener('pointerup', release, true)
  view?.addEventListener('pointercancel', release, true)
  return () => {
    view?.removeEventListener('pointerup', release, true)
    view?.removeEventListener('pointercancel', release, true)
  }
})
const holding = computed(() => open.value || barOpen.value)
const toolbarStops = computed(() => toolbarStop())
const barStops = computed(() => toolbarStop())
const placeBar = computed(
  () => () => placeSelectionBar(bar.value, held.value.editor?.selectionRect()),
)
const describedByAll = computed(
  () =>
    [props.ariaDescribedby, props.maxLength === undefined ? undefined : countId.value]
      .filter((part) => part !== undefined)
      .join(' ') || undefined,
)
const suggesting = computed(() => props.entities.length > 0)
const attributes = computed(
  () =>
    ({
      id: surfaceId.value,
      role: 'textbox',
      'aria-multiline': 'true',
      'aria-label': props.ariaLabel,
      'aria-labelledby': props.ariaLabelledby,
      'aria-describedby': describedByAll.value,
      'aria-required': props.ariaRequired === true ? 'true' : undefined,
      'aria-invalid': props.invalid || overLimit.value ? 'true' : undefined,
      'aria-disabled': props.disabled ? 'true' : undefined,
      'aria-readonly': !props.disabled && unwritable.value ? 'true' : undefined,
