            size="sm"
            :label="cancelLabel"
            :disabled="disabled"
            @click="emit('cancel')"
          />
          <Button
            variant="solid"
            tone="accent"
            size="sm"
            :label="submitLabel ?? ''"
            :disabled="disabled || empty || overLimit"
            :loading="pending"
            @click="submit()"
          />
        </div>
      </div>
    </div>
    <template v-if="!footerDrawn">
      <!-- count -->
      <p
        v-if="maxLength !== undefined"
        :class="styles.count"
        :id="countId"
        :data-state="overLimit ? 'over' : undefined"
      >
        {{ overLimit ? say.overLimit(over) : say.count(length, maxLength) }}
      </p>
    </template>
    <!-- suggestions -->
    <div
      v-if="open && source !== undefined"
      ref="panel"
      :class="styles.suggestions"
      data-rich-text-input-part="suggestions"
      @mousedown="$event.preventDefault()"
    >
      <!-- list -->
      <ul
        v-if="shown.length > 0"
        :class="styles.listbox"
        :id="listId"
        role="listbox"
        :aria-label="source?.label"
      >
        <template v-for="(option, index) in shown" :key="option.id">
          <!-- option -->
          <li
            :class="styles.option"
            :id="`${uid}-suggestion-${index}`"
            role="option"
            :aria-selected="index === activeOption ? 'true' : 'false'"
            :data-highlighted="index === activeOption ? '' : undefined"
            @pointermove="index !== activeOption && (highlight = { key: listKey, index })"
            @click="pick(index)"
          >
            <span v-if="option.leading !== undefined" :class="styles.leading" aria-hidden="true">
              <component :is="option.leading" />
            </span>
            <span v-else-if="option.icon !== undefined" :class="styles.glyph">
              <Icon :name="option.icon" size="sm" />
            </span>
            <span :class="styles.text">
              <span :class="styles.label">
                {{ option.label }}
              </span>
              <span v-if="option.description !== undefined" :class="styles.description">
                {{ option.description }}
              </span>
            </span>
          </li>
        </template>
      </ul>
      <div v-if="loading" :class="styles.rows" aria-hidden="true">
        <template v-for="row in [0, 1, 2]" :key="row">
          <div :class="styles.row">
            <Skeleton textStep="sm" />
          </div>
        </template>
      </div>
      <div v-if="failed" :class="styles.error" aria-hidden="true">
        {{ source?.error }}
      </div>
      <div
        v-if="!loading && !failed && shown.length === 0"
        :class="styles.empty"
        aria-hidden="true"
      >
        {{ say.noSuggestions }}
      </div>
    </div>
    <!-- status -->
    <div :class="styles.status" role="status" aria-live="polite">
      <span v-if="said.text !== ''" :key="said.at">
        {{ said.text }}
      </span>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="serializeRichText(doc)"
      :disabled="disabled"
    />
  </div>
</template>
